function Convert-JsonToNestedHashtable {
    param(
        [Parameter(Mandatory=$true)]
        [string]$Path
    )

    if (-not (Test-Path $Path)) {
        Write-Error "File not found at path: $Path"
        return $null
    }

    try {
        $jsonContent = Get-Content -Path $Path -Raw
        $jsonObject = ConvertFrom-Json $jsonContent
        return $jsonObject | ConvertTo-NestedHashtable
    } catch {
        Write-Error "An error occurred while processing the JSON file: $($_.Exception.Message)"
        return $null
    }
}

function ConvertTo-NestedHashtable($obj) {
    if ($obj -is [hashtable]) {
        $newHash = @{}
        foreach ($key in $obj.Keys) {
            $value = $obj[$key]
            if ($value -is [hashtable] -or $value -is [array]) {
                $newHash[$key] = ConvertTo-NestedHashtable($value)
            } else {
                $newHash[$key] = $value
            }
        }
        return $newHash
    } elseif ($obj -is [array]) {
        return $obj | ForEach-Object { ConvertTo-NestedHashtable($_) }
    } else {
        return $obj
    }
}
