using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

public class WordCounter
{
    public static void Main(string[] args)
    {
        if (args.Length == 0 || string.IsNullOrEmpty(args[0]))
        {
            Console.WriteLine("Please provide a text file path as the first argument.");
            return;
        }

        string filePath = args[0];

        if (!File.Exists(filePath))
        {
            Console.WriteLine($"Error: File not found at {filePath}");
            return;
        }

        try
        {
            string content = File.ReadAllText(filePath);
            var wordCounts = new Dictionary<string, int>();

            // Simple tokenization and normalization
            var words = content.Split(new char[] { ' ', '\r', '\n', '.', ',', '!', '?', ';', ':', '"', "'", '-', '(', ')', '[', ']', '{', '}', '<', '>' }, StringSplitOptions.RemoveEmptyEntries)
                                .Select(w => w.ToLower())
                                .Where(w => !string.IsNullOrWhiteSpace(w));

            foreach (var word in words)
            {
                if (wordCounts.ContainsKey(word))
                    wordCounts[word]++;
                else
                    wordCounts[word] = 1;
            }

            // Get the top 10 most frequent words
            var topWords = wordCounts.OrderByDescending(kvp => kvp.Value)
                                   .Take(10)
                                   .ToList();

            Console.WriteLine("Top 10 Most Frequent Words:");
            foreach (var item in topWords)
            {
                Console.WriteLine($"{item.Key}: {item.Value}");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
