using System;
using System.IO;
using System.Threading.Tasks;

public class FileLengthReader
{
    public static async Task Main(string[] args)
    {
        if (args.Length != 2)
        {
            Console.WriteLine("Usage: FileLengthReader <file1_path> <file2_path>");
            return;
        }

        string file1Path = args[0];
        string file2Path = args[1];

        try
        {
            Task<long> lengthTask1 = ReadFileLengthAsync(file1Path);
            Task<long> lengthTask2 = ReadFileLengthAsync(file2Path);

            long length1 = await lengthTask1;
            long length2 = await lengthTask2;

            Console.WriteLine($"Combined length: {length1 + length2}");
        }
        catch (FileNotFoundException ex)
        {
            Console.WriteLine($"Error: File not found - {ex.Message}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }

    private static async Task<long> ReadFileLengthAsync(string path)
    {
        if (!File.Exists(path))
        {
            throw new FileNotFoundException($"The file was not found at path: {path}");
        }
        // Use FileStream with FileShare.Read to allow concurrent access if needed, 
        // though Length property is usually fast and thread-safe for reading metadata.
        using (var stream = new FileStream(path, FileMode.Open, FileAccess.Read))
        {
            return await stream.Length;
        }
    }
}
