public class FileLister
{
    public static void Main(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Usage: FileLister <folderPath>");
            return;
        }

        string startPath = args[0];
        if (!Directory.Exists(startPath))
        {
            Console.WriteLine($"Error: Directory not found at {startPath}");
            return;
        }

        List<FileInfo> largeFiles = new List<FileInfo>();
        FindLargeFilesRecursive(startPath, 100 * 1024 * 1024, largeFiles);

        // Sort by length descending (largest first)
        largeFiles.Sort((a, b) => b.Length.CompareTo(a.Length));

        foreach (var file in largeFiles)
        {
            Console.WriteLine($"{file.Length / (1024 * 1024.0):F2} MB - {file.FullName}");
        }
    }

    private static void FindLargeFilesRecursive(string path, long minSize, List<FileInfo> results)
    {
        try
        {
            // Check files in the current directory
            foreach (var file in Directory.GetFiles(path))
            {
                FileInfo info = new FileInfo(file);
                if (info.Length >= minSize)
                {
                    results.Add(info);
                }
            }

            // Recurse into subdirectories
            foreach (var dir in Directory.GetDirectories(path))
            {
                FindLargeFilesRecursive(dir, minSize, results);
            }
        }
        catch (UnauthorizedAccessException)
        {
            // Ignore directories we don't have permission to access
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
