using System;
using System.IO;

public class FolderWatcher
{
    private static FileSystemWatcher _watcher;

    public static void Main(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Usage: FolderWatcher <path_to_watch>");
            return;
        }

        string path = args[0];
        if (!Directory.Exists(path))
        {
            Console.WriteLine($"Directory not found: {path}");
            return;
        }

        _watcher = new FileSystemWatcher(path)
        {
            IncludeSubdirectories = false,
            NotifyFilter = NotifyFilters.FileName | NotifyFilters.LastWrite
        };

        _watcher.Created += OnFileAction;
        _watcher.Changed += OnFileAction;
        _watcher.Deleted += OnFileAction;
        _watcher.Renamed += OnFileAction;

        _watcher.EnableRaisingEvents = true;
        Console.WriteLine($"Watching folder: {path}. Press Enter to stop.");
        Console.ReadLine();
    }

    private static void OnFileAction(object sender, FileSystemEventArgs e)
    {
        if (e is RenamedEventArgs re)
        {
            Console.WriteLine($"Renamed: From '{re.OldName}' to '{re.Name}'");
        }
        else if (e.ChangeType == WatcherChangeType.Created)
        {
            Console.WriteLine($"Created: {e.Name}");
        }
        else if (e.ChangeType == WatcherChangeType.Changed)
        {
            Console.WriteLine($"Changed: {e.Name}");
        }
        else if (e.ChangeType == WatcherChangeType.Deleted)
        {
            Console.WriteLine($"Deleted: {e.Name}");
        }
    }
}
