using System;
using System.Collections.Generic;
using System.Linq;

public class Order
{
    public string Customer { get; set; }
    public decimal Amount { get; set; }
}

public class Program
{
    public static void Main()
    {
        List<Order> orders = new List<Order>
        {
            new Order { Customer = "Alice", Amount = 100.50m },
            new Order { Customer = "Bob", Amount = 250.75m },
            new Order { Customer = "Alice", Amount = 50.00m },
            new Order { Customer = "Charlie", Amount = 300.00m },
            new Order { Customer = "Bob", Amount = 150.25m }
        };

        // Calculate total per customer and find the single biggest order overall
        var customerTotals = orders
            .GroupBy(o => o.Customer)
            .Select(g => new { Customer = g.Key, Total = g.Sum(o => o.Amount) });

        var biggestOrder = orders.OrderByDescending(o => o.Amount).First();

        // Combine results and sort by total descending
        var finalReport = customerTotals
            .Select(ct => new { ct.Customer, ct.Total, BiggestOrderAmount = biggestOrder.Amount })
            .OrderByDescending(r => r.Total)
            .ToList();

        Console.WriteLine("--- Customer Totals (Highest Total First) ---");
        foreach (var item in finalReport)
        {
            Console.WriteLine($"{item.Customer}: Total = {item.Total:C}");
        }

        Console.WriteLine("\n--- Single Biggest Order ---");
        Console.WriteLine($"Customer: {biggestOrder.Customer}, Amount: {biggestOrder.Amount:C}");
    }
}
