class Stack {
    constructor() {
        this.items = [];
    }

    push(element) {
        this.items.push(element);
    }

    pop() {
        if (this.isEmpty()) {
            return "Stack is empty";
        }
        return this.items.pop();
    }

    peek() {
        if (this.isEmpty()) {
            return "Stack is empty";
        }
        return this.items[0];
    }

    get size() {
        return this.items.length;
    }

    isEmpty() {
        return this.items.length === 0;
    }
}

// Example usage:
const stack = new Stack();
console.log("Is empty:", stack.isEmpty()); // true
stack.push(10);
stack.push(20);
console.log("Size after pushes:", stack.size); // 2
console.log("Peek:", stack.peek()); // 10 (Note: Standard stack peek is usually the top element, which is at index length-1)

// Corrected Peek implementation for LIFO behavior:
class StackLIFO {
    constructor() {
        this.items = [];
    }

    push(element) {
        this.items.push(element);
    }

    pop() {
        if (this.isEmpty()) return undefined;
        return this.items.pop();
    }

    peek() {
        if (this.isEmpty()) return undefined;
        return this.items[this.items.length - 1]; // Top element
    }

    get size() {
        return this.items.length;
    }

    isEmpty() {
        return this.items.length === 0;
    }
}

const stackLIFO = new StackLIFO();
stackLIFO.push(10);
stackLIFO.push(20);
console.log("Size:", stackLIFO.size); // 2
console.log("Peek (Top):", stackLIFO.peek()); // 20
console.log("Pop:", stackLIFO.pop()); // 20
console.log("Size after pop:", stackLIFO.size); // 1
