function Find-DuplicateFiles {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [switch]$Recurse
    )

    Set-StrictMode -Version 2.0
    $ErrorActionPreference = 'Stop'

    try {
        if ($Recurse) {
            $files = Get-ChildItem -Path $Path -File -Recurse -ErrorAction SilentlyContinue
        } else {
            $files = Get-ChildItem -Path $Path -File -ErrorAction SilentlyContinue
        }

        $fileHashes = @{}

        foreach ($file in $files) {
            try {
                $hash = Get-FileHash -Path $file.FullName -Algorithm SHA256 | Select-Object -ExpandProperty Hash
                if (-not $hash) { continue }

                if (-not $fileHashes.ContainsKey($hash)) {
                    $fileHashes[$hash] = @()
                }
                $fileHashes[$hash] += $file.FullName
            }
            catch {
                Write-Error ("Could not hash file $($file.Name): " + $_.Exception.Message)
            }
        }

        $duplicates = @{}
        foreach ($hash in $fileHashes.Keys) {
            if ($fileHashes[$hash].Count -gt 1) {
                $duplicates[$hash] = $fileHashes[$hash]
            }
        }

        return $duplicates | ForEach-Object {
            [PSCustomObject]@{
                Hash = $_.Key
                Files = $_.Value
            }
        }
    }
    catch {
        Write-Error ("An error occurred: " + $_.Exception.Message)
        exit 1
    }
}
```

