    static void Main(string[] args)
    {
        string root = args.Length > 0 ? args[0] : ".";
        const long limit = 100L * 1024 * 1024; // 100 MB

        List<FileInfo> largeFiles = new List<FileInfo>();

        try
        {
            foreach (string file in Directory.EnumerateFiles(root, "*", SearchOption.AllDirectories))
            {
                FileInfo fi = new FileInfo(file);
                if (fi.Length > limit)
                {
                    largeFiles.Add(fi);
                }
            }

            // Sort files by size in descending order
            largeFiles.Sort((a, b) => b.Length.CompareTo(a.Length));

            foreach (FileInfo fi in largeFiles)
            {
                Console.WriteLine("{0,10:N1} MB  {1}", fi.Length / 1048576.0, fi.FullName);
            }
        }
        catch (UnauthorizedAccessException ex)
        {
            Console.WriteLine("Access denied to a folder: " + ex.Message);
        }
        catch (Exception ex)
        {
            Console.WriteLine("An error occurred: " + ex.Message);
        }
    }
}
